"""Compare hypothetical homes using only the trusted, locally exported model."""
from pathlib import Path
import json
import numpy as np
import pandas as pd
import torch
import joblib
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

ROOT = Path(__file__).resolve().parent
ARTIFACTS = ROOT / 'modelos_exportados'
OUT = ROOT / 'comparativa_casas'
OUT.mkdir(exist_ok=True)
# This file is the known artifact generated by our own course notebook.
model = torch.load(ARTIFACTS / 'casas_completo.pt', map_location='cpu', weights_only=False)
model.eval()
scaler = joblib.load(ARTIFACTS / 'casas_completo_scaler.joblib')

def predict(frame):
    values = torch.tensor(scaler.transform(frame[['m2','balcon','ascensor']]), dtype=torch.float32)
    with torch.inference_mode():
        return model(values).numpy().ravel() * 1000  # target was thousands of USD

homes = pd.DataFrame([
    ('A',40,0,0),('B',65,0,0),('C',90,0,0),('D',120,0,0),
    ('E',65,1,0),('F',65,0,1),('G',65,1,1),('H',120,1,1)],
    columns=['casa','m2','balcon','ascensor'])
homes['precio_estimado_usd'] = predict(homes)
homes['precio_estimado_usd_m2'] = homes['precio_estimado_usd'] / homes['m2']
homes.to_csv(OUT / 'comparativa_casas.csv', index=False, encoding='utf-8-sig')

weights = model.weight.detach().numpy().ravel() / scaler.scale_
intercept = float(model.bias.item() - (weights * scaler.mean_).sum())
manual = (homes[['m2','balcon','ascensor']].values @ weights + intercept) * 1000
np.testing.assert_allclose(manual, homes['precio_estimado_usd'], rtol=1e-5)
assert homes.iloc[:4]['precio_estimado_usd'].is_monotonic_increasing
assert homes.iloc[:4]['precio_estimado_usd_m2'].is_monotonic_decreasing
eligible = homes[(homes.precio_estimado_usd <= 160000) & (homes.m2 >= 60)]
summary = {
    'criterio': 'menor precio estimado por m2, solo entre los ocho escenarios definidos',
    'menor_precio_total': homes.loc[homes.precio_estimado_usd.idxmin(),'casa'],
    'menor_precio_m2': homes.loc[homes.precio_estimado_usd_m2.idxmin(),'casa'],
    'mayor_precio_total': homes.loc[homes.precio_estimado_usd.idxmax(),'casa'],
    'ejemplo_restringido': {'presupuesto_usd':160000,'minimo_m2':60,
        'menor_precio_m2_entre_elegibles': eligible.loc[eligible.precio_estimado_usd_m2.idxmin(),'casa']},
    'coeficientes_miles_usd_escala_original': dict(zip(['m2','balcon','ascensor'],weights.tolist())),
    'intercepto_miles_usd':intercept,
    'entrenamiento_nuevo': False,
    'nota': 'Escenarios sintéticos; no son anuncios ni precios de mercado. No se evaluó calidad, barrio o estado.'}
(OUT / 'resumen.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')

plt.rcParams.update({'font.family':'DejaVu Sans','font.size':11})
fig, axes = plt.subplots(1,2,figsize=(11.5,4.3),layout='constrained')
colors=['#234f40','#af7e2f','#4a7b9c','#a05a66']
for (balcony,lift), color in zip([(0,0),(1,0),(0,1),(1,1)],colors):
    frame=pd.DataFrame({'m2':np.arange(40,121),'balcon':balcony,'ascensor':lift})
    pred=predict(frame)
    label={(0,0):'Sin balcón ni ascensor',(1,0):'Con balcón',(0,1):'Con ascensor',(1,1):'Con ambos'}[(balcony,lift)]
    axes[0].plot(frame.m2,pred/1000,label=label,color=color,lw=2)
    axes[1].plot(frame.m2,pred/frame.m2,label=label,color=color,lw=2)
axes[0].set(title='Más superficie: mayor precio total',xlabel='Superficie (m²)',ylabel='Precio estimado (miles de US$)')
axes[1].set(title='El precio por m² puede bajar',xlabel='Superficie (m²)',ylabel='Precio estimado (US$/m²)')
for ax in axes: ax.grid(alpha=.2);ax.spines[['top','right']].set_visible(False)
axes[1].legend(fontsize=8,frameon=False)
fig.savefig(OUT/'precio_y_superficie.png',dpi=180)
plt.close(fig)
print(homes.round(2).to_string(index=False))
print(json.dumps(summary,ensure_ascii=False,indent=2))
